test('lineVat is used in invoiceTotals', () => {
  const line = { qty: 100, unitPrice: 50, discountPercent: 10, vatRate: 21 };
  const expectedVat = lineVat(line);

  const invoice = { lines: [line] };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.vat, expectedVat);
});

test('invoiceTotals with bulk discount (qty >= 10)', () => {
  // 10 qty * 100 unitPrice = 1000
  // No line discount
  // Bulk discount (2.5% of 1000) = 25
  // After both discounts = 975
  // VAT (21%) = 204.75 -> 205
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 25);
  assert.equal(totals.vat, 205); // 975 * 0.21 = 204.75 -> 205
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 1180); // 1000 - 25 + 205
});

test('invoiceTotals with qty = 9 (no bulk discount)', () => {
  // 9 qty * 100 unitPrice = 900
  // No line discount, no bulk discount (qty < 10)
  // VAT (21%) = 189
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 100, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 900);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 189); // 900 * 0.21 = 189
  assert.equal(totals.total, 1089);
});

test('invoiceTotals with bulk discount applied after line discount', () => {
  // 20 qty * 100 unitPrice = 2000
  // Line discount (10%) = 200
  // After line discount = 1800
  // Bulk discount (2.5% of 1800) = 45
  // After both discounts = 1755
  // VAT (21%) = 368.55 -> 369
  const invoice = {
    lines: [
      { qty: 20, unitPrice: 100, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 2000);
  assert.equal(totals.discount, 245); // 200 + 45
  assert.equal(totals.vat, 369); // 1755 * 0.21 = 368.55 -> 369
  assert.equal(totals.total, 2124); // 2000 - 245 + 369
});

test('invoiceTotals bulk discount with multiple lines', () => {
  // Line 1: 15 qty * 100 unitPrice = 1500
  //   Discount (5%) = 75, after = 1425
  //   Bulk (2.5% of 1425) = 36.25 -> 36
  //   After both = 1389, VAT (21%) = 291.69 -> 292
  //
  // Line 2: 5 qty * 100 unitPrice = 500
  //   No discount, no bulk (qty < 10)
  //   VAT (21%) = 105
  const invoice = {
    lines: [
      { qty: 15, unitPrice: 100, discountPercent: 5, vatRate: 21 },
      { qty: 5, unitPrice: 100, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 2000);
  assert.equal(totals.discount, 111); // 75 + 36 + 0
  assert.equal(totals.vat, 397); // 292 + 105
  assert.equal(totals.total, 2286); // 2000 - 111 + 397
});

test('invoiceTotals bulk discount with 0% VAT line', () => {
  // 10 qty * 100 unitPrice = 1000
  // No line discount
  // Bulk discount (2.5%) = 25
  // After both = 975
  // VAT (0%) = 0
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 25);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 975);
});

test('invoiceTotals bulk discount with 9% VAT line', () => {
  // 10 qty * 200 unitPrice = 2000
  // No line discount
  // Bulk discount (2.5%) = 50
  // After both = 1950
  // VAT (9%) = 175.5 -> 176
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 200, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 2000);
  assert.equal(totals.discount, 50);
  assert.equal(totals.vat, 176); // 1950 * 0.09 = 175.5 -> 176
  assert.equal(totals.total, 2126);
});

test('invoiceTotals bulk discount with 20 units', () => {
  // 20 qty * 50 unitPrice = 1000
  // No line discount
  // Bulk discount (2.5%) = 25
  // After both = 975
  // VAT (21%) = 204.75 -> 205
  const invoice = {
    lines: [
      { qty: 20, unitPrice: 50, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 25);
  assert.equal(totals.vat, 205);
  assert.equal(totals.total, 1180);
});

test('invoiceTotals bulk discount with 100 units', () => {
  // 100 qty * 10 unitPrice = 1000
  // No line discount
  // Bulk discount (2.5%) = 25
  // After both = 975
  // VAT (21%) = 204.75 -> 205
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 25);
  assert.equal(totals.vat, 205);
  assert.equal(totals.total, 1180);
});

test('invoiceTotals bulk discount boundary at qty = 10', () => {
  // Test that exactly 10 units triggers bulk discount
  const invoice10 = { lines: [{ qty: 10, unitPrice: 100, vatRate: 0 }] };
  const totals10 = invoiceTotals(invoice10);

  const invoice9 = { lines: [{ qty: 9, unitPrice: 100, vatRate: 0 }] };
  const totals9 = invoiceTotals(invoice9);

  // qty 10 should have discount
  assert.equal(totals10.discount, 25);
  // qty 9 should not
  assert.equal(totals9.discount, 0);
  // Difference should be exactly 25
  assert.equal(totals10.subtotal - totals9.subtotal, 100);
  assert.equal(totals10.discount - totals9.discount, 25);
});

test('invoiceTotals bulk discount with tier discount and bulk discount', () => {
  // 10 qty * 9500 unitPrice (DEV-HOUR) = 95000
  // Tier discount (5%) = 4750
  // After tier = 90250
  // Bulk (2.5% of 90250) = 2256.25 -> 2256
  // After both = 87994
  // VAT (21%) = 18478.74 -> 18479
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500, discountPercent: 5, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 7006); // 4750 + 2256
  assert.equal(totals.vat, 18479); // 87994 * 0.21
  assert.equal(totals.total, 106473);
});

