test('invoiceTotals with complex line discounts', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 9500, discountPercent: 5, vatRate: 21 }, // DEV-HOUR with gold discount (no bulk)
      { qty: 1, unitPrice: 8500, discountPercent: 2.5, vatRate: 21 }, // DES-HOUR with silver discount (no bulk)
      { qty: 100, unitPrice: 50, discountPercent: 0, vatRate: 21 }, // STICKER with bulk discount
    ],
  };
  const totals = invoiceTotals(invoice);

  // DEV-HOUR: 9500, discount 475 (5%), no bulk (qty < 10), after 9025, vat 1895
