import test from 'node:test';
import assert from 'node:assert/strict';
import { isValidDiscountPercent, lineTotal, lineVat, invoiceTotals } from '../src/totals.js';

test('isValidDiscountPercent accepts 0', () => {
  assert.equal(isValidDiscountPercent(0), true);
});

test('isValidDiscountPercent accepts 100', () => {
  assert.equal(isValidDiscountPercent(100), true);
});

test('isValidDiscountPercent accepts decimal values', () => {
  assert.equal(isValidDiscountPercent(5.5), true);
  assert.equal(isValidDiscountPercent(2.5), true);
});

test('isValidDiscountPercent rejects negative', () => {
  assert.equal(isValidDiscountPercent(-1), false);
});

test('isValidDiscountPercent rejects > 100', () => {
  assert.equal(isValidDiscountPercent(101), false);
});

test('isValidDiscountPercent rejects non-number', () => {
  assert.equal(isValidDiscountPercent('50'), false);
  assert.equal(isValidDiscountPercent(null), false);
  assert.equal(isValidDiscountPercent(undefined), false);
});

test('lineTotal calculates qty times unitPrice', () => {
  const line = { qty: 5, unitPrice: 100 };
  assert.equal(lineTotal(line), 500);
});

test('lineTotal with single unit', () => {
  const line = { qty: 1, unitPrice: 9500 };
  assert.equal(lineTotal(line), 9500);
});

test('lineTotal with large quantities', () => {
  const line = { qty: 1000, unitPrice: 100 };
  assert.equal(lineTotal(line), 100000);
});

test('lineVat calculates VAT on amount after discount', () => {
  // 100 qty * 50 unitPrice = 5000
  // No discount
  // VAT at 21% = 5000 * 0.21 = 1050
  const line = { qty: 100, unitPrice: 50, vatRate: 21 };
  assert.equal(lineVat(line), 1050);
});

test('lineVat with discount', () => {
  // 100 qty * 50 unitPrice = 5000
  // 10% discount = 500
  // Amount after discount = 4500
  // VAT at 21% = 4500 * 0.21 = 945
  const line = { qty: 100, unitPrice: 50, discountPercent: 10, vatRate: 21 };
  assert.equal(lineVat(line), 945);
});

test('lineVat with 0% VAT', () => {
  const line = { qty: 10, unitPrice: 100, vatRate: 0 };
  assert.equal(lineVat(line), 0);
});

test('lineVat with 9% VAT', () => {
  // 100 qty * 50 unitPrice = 5000
  // No discount
  // VAT at 9% = 5000 * 0.09 = 450
  const line = { qty: 100, unitPrice: 50, vatRate: 9 };
  assert.equal(lineVat(line), 450);
});

test('lineVat rounds to cents', () => {
  // 10 qty * 1 unitPrice = 10
  // 5.5% discount = 0.55 -> rounds to 1
  // Amount after discount = 9
  // VAT at 21% = 1.89 -> rounds to 2
  const line = { qty: 10, unitPrice: 1, discountPercent: 5.5, vatRate: 21 };
  const vat = lineVat(line);
  assert.equal(vat, 2);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 50, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 5000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 1050);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 6050);
});

test('invoiceTotals with line discount', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 50, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 5000);
  assert.equal(totals.discount, 500);
  assert.equal(totals.vat, 945);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 5445);
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 50, vatRate: 21 }, // Qty >= 10, has bulk discount
      { qty: 50, unitPrice: 100, vatRate: 9 }, // Qty >= 10, has bulk discount
    ],
  };
  const totals = invoiceTotals(invoice);

  // Line 1: 100*50 = 5000, bulk (2.5%) = 125, after = 4875, VAT (21%) = 1023.75 -> 1024
  // Line 2: 50*100 = 5000, bulk (2.5%) = 125, after = 4875, VAT (9%) = 438.75 -> 439
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 250); // 125 + 125
  assert.equal(totals.vat, 1463); // 1024 + 439
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 11213);
});

test('invoiceTotals with voucher', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 50, vatRate: 21 },
    ],
    voucher: { code: 'SUMMER', amount: 500 },
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 5000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 1050);
  assert.equal(totals.voucher, 500);
  assert.equal(totals.total, 5550);
});

test('invoiceTotals with tier discount (applied as line discount)', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 50, discountPercent: 5, vatRate: 21 }, // Gold tier discount + bulk discount
    ],
  };
  const totals = invoiceTotals(invoice);

  // Line discount: 5000 * 5% = 250, after = 4750
  // Bulk discount (qty >= 10): 4750 * 2.5% = 118.75 -> 119
  // After both: 4750 - 119 = 4631
  // VAT: 4631 * 21% = 972.51 -> 973
  assert.equal(totals.subtotal, 5000);
  assert.equal(totals.discount, 369); // 250 + 119
  assert.equal(totals.vat, 973);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 5604);
});

test('invoiceTotals with multiple lines and mixed discounts', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 50, discountPercent: 5, vatRate: 21 }, // Qty >= 10
      { qty: 50, unitPrice: 100, discountPercent: 0, vatRate: 9 }, // Qty >= 10
    ],
    voucher: { code: 'PROMO', amount: 100 },
  };
  const totals = invoiceTotals(invoice);

  // Line 1: 5000, discount 5%=250, after 4750, bulk 2.5%=119, after 4631, vat 21%=972.51->973
  // Line 2: 5000, discount 0, bulk 2.5%=125, after 4875, vat 9%=438.75->439
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 494); // 250 + 119 + 0 + 125
  assert.equal(totals.vat, 1412); // 973 + 439
  assert.equal(totals.voucher, 100);
  assert.equal(totals.total, 11306); // 10000 - 494 + 1412 - 100
});

test('invoiceTotals with zero VAT lines', () => {
  const invoice = {
    lines: [
      { qty: 100, unitPrice: 50, vatRate: 0 },
      { qty: 200, unitPrice: 25, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 10000); // 5000 + 5000
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 10000);
});

test('invoiceTotals prevents negative total', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 100, vatRate: 0 },
    ],
    voucher: { code: 'HUGE', amount: 500 },
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.total, 0); // Math.max(0, ...)
});

test('invoiceTotals with empty lines array', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 0);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals with complex line discounts', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 9500, discountPercent: 5, vatRate: 21 }, // DEV-HOUR with gold discount (no bulk)
      { qty: 1, unitPrice: 8500, discountPercent: 2.5, vatRate: 21 }, // DES-HOUR with silver discount (no bulk)
      { qty: 100, unitPrice: 50, discountPercent: 0, vatRate: 21 }, // STICKER with bulk discount
    ],
  };
  const totals = invoiceTotals(invoice);

  // DEV-HOUR: 9500, discount 475 (5%), no bulk (qty < 10), after 9025, vat 1895
  // DES-HOUR: 8500, discount 212 (2.5%), no bulk (qty < 10), after 8288, vat 1740
  // STICKER: 5000, discount 0, bulk (qty >= 10): 5000*2.5% = 125, after 4875, vat 1024
  assert.equal(totals.subtotal, 23000);
  assert.equal(totals.discount, 812); // 475 + 212 + 125
  assert.equal(totals.voucher, 0);
});

test('lineTotal is used consistently in invoiceTotals', () => {
  const line = { qty: 10, unitPrice: 100, vatRate: 21 };
  const lineAmt = lineTotal(line);

  const invoice = { lines: [line] };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, lineAmt);
});

test('invoiceTotals with single line without bulk discount', () => {
  // Use qty < 10 so bulk discount doesn't apply
  // This allows us to verify lineVat is used correctly
  const line = { qty: 5, unitPrice: 50, discountPercent: 10, vatRate: 21 };
  const expectedVat = lineVat(line);

  const invoice = { lines: [line] };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.vat, expectedVat);
});

test('invoiceTotals with bulk discount (qty >= 10)', () => {
  // 10 qty * 100 unitPrice = 1000
  // No line discount
  // Bulk discount (2.5% of 1000) = 25
  // After both discounts = 975
  // VAT (21%) = 204.75 -> 205
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 25);
  assert.equal(totals.vat, 205); // 975 * 0.21 = 204.75 -> 205
  assert.equal(totals.voucher, 0);
  assert.equal(totals.total, 1180); // 1000 - 25 + 205
});

test('invoiceTotals with qty = 9 (no bulk discount)', () => {
  // 9 qty * 100 unitPrice = 900
  // No line discount, no bulk discount (qty < 10)
  // VAT (21%) = 189
  const invoice = {
    lines: [
      { qty: 9, unitPrice: 100, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 900);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 189); // 900 * 0.21 = 189
  assert.equal(totals.total, 1089);
});

test('invoiceTotals with bulk discount applied after line discount', () => {
  // 20 qty * 100 unitPrice = 2000
  // Line discount (10%) = 200
  // After line discount = 1800
  // Bulk discount (2.5% of 1800) = 45
  // After both discounts = 1755
  // VAT (21%) = 368.55 -> 369
  const invoice = {
    lines: [
      { qty: 20, unitPrice: 100, discountPercent: 10, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 2000);
  assert.equal(totals.discount, 245); // 200 + 45
  assert.equal(totals.vat, 369); // 1755 * 0.21 = 368.55 -> 369
  assert.equal(totals.total, 2124); // 2000 - 245 + 369
});

test('invoiceTotals bulk discount with multiple lines', () => {
  // Line 1: 15 qty * 100 unitPrice = 1500
  //   Discount (5%) = 75, after = 1425
  //   Bulk (2.5% of 1425) = 36.25 -> 36
  //   After both = 1389, VAT (21%) = 291.69 -> 292
  //
  // Line 2: 5 qty * 100 unitPrice = 500
  //   No discount, no bulk (qty < 10)
  //   VAT (21%) = 105
  const invoice = {
    lines: [
      { qty: 15, unitPrice: 100, discountPercent: 5, vatRate: 21 },
      { qty: 5, unitPrice: 100, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 2000);
  assert.equal(totals.discount, 111); // 75 + 36 + 0
  assert.equal(totals.vat, 397); // 292 + 105
  assert.equal(totals.total, 2286); // 2000 - 111 + 397
});

test('invoiceTotals bulk discount with 0% VAT line', () => {
  // 10 qty * 100 unitPrice = 1000
  // No line discount
  // Bulk discount (2.5%) = 25
  // After both = 975
  // VAT (0%) = 0
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 100, vatRate: 0 },
