  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 25);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 975);
});

test('invoiceTotals bulk discount with 9% VAT line', () => {
  // 10 qty * 200 unitPrice = 2000
  // No line discount
  // Bulk discount (2.5%) = 50
  // After both = 1950
  // VAT (9%) = 175.5 -> 176
